import java.io.*;
import java.util.*;

public class E {
    static final int MOD = 998_244_353;

    public static void main(String[] args) throws Exception {
        new E().run();
    }

    void run() throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int n = fs.nextInt();
        int m = fs.nextInt();
        int l = fs.nextInt();
        int r = fs.nextInt();
        long power = 1L * n * m;

        if ((n & 1) == 1 && (m & 1) == 1) {
            long total = r - l + 1;
            out.println(scalarPow(total, power));
        } else {
            int even = r / 2 - (l + 1) / 2 + 1;
            int odd = r - l + 1 - even;
            long[] res = symmetricPow(even, odd, power);
            out.println(res[0]);
        }
        out.flush();
    }

    long scalarPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = res * a % MOD;
            }
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    long[] symmetricPow(long p, long q, long e) {
        long rp = 1;
        long rq = 0;
        while (e > 0) {
            if ((e & 1) == 1) {
                long np = (rp * p + rq * q) % MOD;
                long nq = (rp * q + rq * p) % MOD;
                rp = np;
                rq = nq;
            }
            long np = (p * p + q * q) % MOD;
            long nq = (2 * p % MOD) * q % MOD;
            p = np;
            q = nq;
            e >>= 1;
        }
        return new long[]{rp, rq};
    }

    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
